import { createWriteStream } from 'node:fs';
import { mkdtemp, readFile, rm, stat } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path, { basename, dirname, join } from 'node:path';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';
import { buildStudio, compareDependencyVersions } from '@sanity/cli-build/_internal/build';
import { getLocalPackageVersion } from '@sanity/cli-core';
import { pack } from 'tar-fs';
export async function prepareStudioAsset({ blueprintFileDir, resource, }) {
    // validate resource has an appId
    const appId = getAppId(resource);
    if (!appId) {
        return {
            success: false,
            async cleanup() {
                // no op
            },
            error: `Unable to determine appId for sanity.studio resource '${resource.name}'`,
        };
    }
    let cleanup = async () => {
        // no op
    };
    const studioPath = path.resolve(blueprintFileDir, resource.src);
    // set only when auto-updates is on, because the build compares versions only then
    let mismatchedPackages;
    try {
        const studioPathStat = await stat(studioPath);
        if (!studioPathStat.isDirectory()) {
            return {
                success: false,
                cleanup,
                error: `Property 'src' on resource with type '${resource.type}' must be a directory`,
            };
        }
    }
    catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        return {
            success: false,
            cleanup,
            error: `Unable to read given 'src' on resource with type '${resource.type}': ${msg}`,
        };
    }
    try {
        const outDir = await mkdtemp(join(tmpdir(), `studio-build-`));
        const outFile = `${outDir}.tar.gz`;
        cleanup = async () => {
            await rm(outDir, { force: true, recursive: true });
            await rm(outFile, { force: true });
        };
        try {
            await buildStudio({
                appId,
                autoUpdatesEnabled: resource.autoUpdates.enabled,
                checkAppId() { },
                async compareDependencyVersions(packages) {
                    const result = await compareDependencyVersions(packages, studioPath, { appId });
                    mismatchedPackages = result.mismatched.map((m) => m.pkg);
                    return result;
                },
                determineBasePath() {
                    return resource.basePath ?? '/';
                },
                isApp: false,
                isWorkbenchApp: false,
                minify: resource.minify ?? true,
                outDir,
                output: createSilentOutput(),
                reactCompiler: resource.reactCompiler || false,
                schemaExtraction: undefined,
                sourceMap: resource.sourceMap ?? false,
                stats: false,
                unattendedMode: true,
                // TODO pass in vite config from the studio resource
                vite: undefined,
                workDir: studioPath,
                eventListener: {
                    onBuildFail({ message }) {
                        throw new Error(message);
                    },
                    onInvalidStyledComponentsVersionRange({ message }) {
                        throw new Error(message);
                    },
                    onNoDeclaredStyledComponentsVersion({ message }) {
                        throw new Error(message);
                    },
                    onNoInstalledSanityVersion({ message }) {
                        throw new Error(message);
                    },
                    onNoInstalledStyledComponentsVersion({ message }) {
                        throw new Error(message);
                    },
                    onPreReleaseInNonInteractiveAutoUpdate({ message }) {
                        throw new Error(message);
                    },
                },
            });
        }
        catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            return {
                success: false,
                cleanup,
                error: message,
            };
        }
        // tar/gzip/write the built output
        await pipeline(pack(dirname(outDir), { entries: [basename(outDir)] }), createGzip(), createWriteStream(outFile));
        const buffer = await readFile(outFile);
        return {
            success: true,
            cleanup,
            outputBuffer: buffer,
            fileExtension: 'tar.gz',
            assetParameter: 'src',
            metadata: {
                sanityVersion: await getInstalledSanityVersion(studioPath),
                mismatchedPackages,
                assetBytes: buffer.length,
            },
        };
    }
    catch (error) {
        return {
            success: false,
            cleanup,
            error: error instanceof Error ? error.message : String(error),
        };
    }
}
function createSilentOutput() {
    return {
        error(input, options) {
            if (typeof options?.exit === 'number') {
                if (input instanceof Error) {
                    throw input;
                }
                throw new Error(input);
            }
            return undefined;
        },
        log() { },
        warn(input) {
            return input;
        },
    };
}
async function getInstalledSanityVersion(studioPath) {
    try {
        return (await getLocalPackageVersion('sanity', studioPath)) ?? undefined;
    }
    catch {
        return undefined;
    }
}
function getAppId(resource) {
    if ('externalId' in resource && typeof resource.externalId === 'string' && resource.externalId) {
        return resource.externalId;
    }
    else if (resource.lifecycle?.ownershipAction?.type === 'attach') {
        return resource.lifecycle.ownershipAction.id;
    }
    return undefined;
}
